                if (BT_activity_base.this.appLastModifiedOnServer.length() > 1) {
                    if (BT_fileManager.doesCachedFileExist(cachedConfigModifiedFileName)) {
                        previousModified = BT_fileManager.readTextFileFromCache(cachedConfigModifiedFileName);
                        BT_debugger.showIt(String.valueOf(BT_activity_base.this.activityName) + ":handleReportToCloudResults previousModified (value on device): " + previousModified);
                    }
                    BT_fileManager.saveTextFileToCache(BT_activity_base.this.appLastModifiedOnServer, cachedConfigModifiedFileName);
                    if (BT_activity_base.this.appLastModifiedOnServer.length() > 3 && previousModified.length() > 3) {
                        if (!BT_activity_base.this.appLastModifiedOnServer.equalsIgnoreCase(previousModified)) {
                            BT_debugger.showIt(String.valueOf(BT_activity_base.this.activityName) + ":handleReportToCloudResults server data changed, app needs refreshed");
                            BT_activity_base.this.confirmRefresh();
                        } else {
                            BT_debugger.showIt(String.valueOf(BT_activity_base.this.activityName) + ":handleReportToCloudResults server data not changed, no refresh needed");
                        }
                    }
                }
            } catch (Exception e) {
                BT_debugger.showIt(String.valueOf(BT_activity_base.this.activityName) + ":handleReportToCloudResults EXCEPTION processing results: " + e.toString());
