    public void getLastLocation() {
        try {
            if (!mspcarshows_appDelegate.foundUpdatedLocation) {
                this.locationUpdateCount = 0;
                if (this.locationManager == null) {
                    this.locationUpdateCount = 0;
                    this.locationManager = (LocationManager) getSystemService("location");
                }
                if (this.locationManager != null) {
                    Location lastLocation = this.locationManager.getLastKnownLocation("gps");
                    if (lastLocation != null) {
                        mspcarshows_appDelegate.rootApp.getRootDevice().setDeviceLatitude(String.valueOf(lastLocation.getLatitude()));
                        mspcarshows_appDelegate.rootApp.getRootDevice().setDeviceLongitude(String.valueOf(lastLocation.getLongitude()));
                        String s = String.valueOf("") + " Lat: " + lastLocation.getLatitude();
                        BT_debugger.showIt(String.valueOf(this.activityName) + ":getLastLocation " + (String.valueOf(String.valueOf(s) + " Lon: " + lastLocation.getLongitude()) + " Accuracy: " + lastLocation.getAccuracy()));
                    }
                    if (this.locationManager.isProviderEnabled("gps")) {
                        this.locationListenerType = "GPS";
                        startListening();
                        return;
                    } else if (this.locationManager.isProviderEnabled("network")) {
                        this.locationListenerType = "NETWORK/CELL";
                        startListening();
                        return;
                    } else {
                        BT_debugger.showIt(String.valueOf(this.activityName) + ":getLastLocation Can't start GPS or Network Services to get location info.");
                        return;
                    }
                }
                BT_debugger.showIt(String.valueOf(this.activityName) + ":getLastLocation locationManager == null?");
            }
        } catch (Exception je) {
            BT_debugger.showIt(String.valueOf(this.activityName) + ":getLastLocation EXCEPTION " + je.toString());
        }
    }

