            BT_debugger.showIt(String.valueOf(this.activityName) + ":transitionToAppHomeScreen splash screen with itemId: " + splashScreenItemId);
            BT_item tmpScreenData = mspcarshows_appDelegate.rootApp.getScreenDataByItemId(splashScreenItemId);
            mspcarshows_appDelegate.rootApp.setCurrentScreenData(tmpScreenData);
