                BT_debugger.showIt(String.valueOf(className) + ": validateApplicationData: No BT_items?");
                return false;
            }
            BT_debugger.showIt(String.valueOf(className) + ": validateApplicationData: No BT_appConfig?");
            return false;
        } catch (Exception e) {
            BT_debugger.showIt(String.valueOf(className) + ":validateApplicationData EXCEPTION trying to parse JSON data? ERROR: " + e.toString());
            return false;
        }
    }

    public boolean parseAppJSONData(String configData) {
        BT_debugger.showIt(String.valueOf(className) + ": parseJSONData");
        this.dataURL = "";
        this.themes.clear();
        this.tabs.clear();
        this.screens.clear();
        this.transitionTypeHistory.clear();
        try {
            JSONObject obj = new JSONObject(configData);
            if (obj.has("BT_appConfig")) {
                JSONObject rootObj = obj.getJSONObject("BT_appConfig");
                if (rootObj.has("BT_items")) {
                    JSONArray BT_items = rootObj.getJSONArray("BT_items");
                    for (int i = 0; i < BT_items.length(); i++) {
                        BT_items.getJSONObject(i);
                        JSONObject rootBT_item = BT_items.getJSONObject(0);
                        BT_debugger.showIt(String.valueOf(className) + ": parsing core settings...");
                        if (rootBT_item.has("itemId")) {
                            this.itemId = rootBT_item.getString("itemId");
                        }
                        if (rootBT_item.has("itemType")) {
                            this.itemType = rootBT_item.getString("itemType");
                        }
                        if (rootBT_item.has("buzztouchAppId")) {
                            this.buzztouchAppId = rootBT_item.getString("buzztouchAppId");
                        }
                        if (rootBT_item.has("buzztouchAPIKey")) {
                            this.buzztouchAPIKey = rootBT_item.getString("buzztouchAPIKey");
                        }
                        if (rootBT_item.has("dataURL")) {
                            this.dataURL = rootBT_item.getString("dataURL");
                        }
                        if (rootBT_item.has("reportToCloudURL")) {
                            this.reportToCloudURL = rootBT_item.getString("reportToCloudURL");
                        }
                        if (rootBT_item.has("name")) {
                            this.name = rootBT_item.getString("name");
                        }
                        if (rootBT_item.has("version")) {
                            this.version = rootBT_item.getString("version");
                        }
                        if (rootBT_item.has("startLocationUpdates")) {
                            this.startLocationUpdates = rootBT_item.getString("startLocationUpdates");
                        }
                        if (rootBT_item.has("allowRotation")) {
                            this.allowRotation = rootBT_item.getString("allowRotation");
                        }
                        if (rootBT_item.has("BT_themes")) {
                            BT_debugger.showIt(String.valueOf(className) + ": parsing themes...");
                            JSONArray BT_themes = rootBT_item.getJSONArray("BT_themes");
                            JSONObject firstBT_theme = BT_themes.getJSONObject(0);
                            if (firstBT_theme.has("itemType") && firstBT_theme.getString("itemType").equalsIgnoreCase("BT_theme")) {
                                BT_item tmpTheme = new BT_item();
                                if (firstBT_theme.has("itemId")) {
                                    tmpTheme.setItemId(firstBT_theme.getString("itemId"));
                                }
                                if (firstBT_theme.has("itemType")) {
                                    tmpTheme.setItemType(firstBT_theme.getString("itemType"));
                                }
                                if (firstBT_theme.has("itemNickname")) {
                                    tmpTheme.setItemNickname(firstBT_theme.getString("itemNickname"));
                                }
                                this.themes.add(tmpTheme);
                                this.rootTheme = tmpTheme;
                                this.rootTheme.setJsonObject(firstBT_theme);
                            }
                        }
                        if (rootBT_item.has("BT_tabs")) {
                            BT_debugger.showIt(String.valueOf(className) + ": parsing tabs...");
                            JSONArray BT_tabs = rootBT_item.getJSONArray("BT_tabs");
                            for (int t = 0; t < BT_tabs.length(); t++) {
                                JSONObject thisTab = BT_tabs.getJSONObject(t);
                                if (thisTab.has("itemType") && thisTab.getString("itemType").equalsIgnoreCase("BT_tab")) {
                                    BT_item tmpTab = new BT_item();
                                    if (thisTab.has("itemId")) {
                                        tmpTab.setItemId(thisTab.getString("itemId"));
                                    }
                                    if (thisTab.has("itemType")) {
                                        tmpTab.setItemType(thisTab.getString("itemType"));
                                    }
                                    if (thisTab.has("itemNickname")) {
                                        tmpTab.setItemNickname(thisTab.getString("itemNickname"));
                                    }
                                    tmpTab.setJsonObject(thisTab);
                                    this.tabs.add(tmpTab);
                                }
                            }
                        }
                        if (rootBT_item.has("BT_screens")) {
                            BT_debugger.showIt(String.valueOf(className) + ": parsing screens...");
                            JSONArray BT_screens = rootBT_item.getJSONArray("BT_screens");
                            for (int s = 0; s < BT_screens.length(); s++) {
                                JSONObject thisScreen = BT_screens.getJSONObject(s);
                                if (thisScreen.has("itemType")) {
                                    BT_item tmpScreen = new BT_item();
                                    if (thisScreen.has("itemId")) {
                                        tmpScreen.setItemId(thisScreen.getString("itemId"));
                                    }
                                    if (thisScreen.has("itemType")) {
                                        tmpScreen.setItemType(thisScreen.getString("itemType"));
                                    }
                                    if (thisScreen.has("itemNickname")) {
                                        tmpScreen.setItemNickname(thisScreen.getString("itemNickname"));
                                    }
                                    tmpScreen.setJsonObject(thisScreen);
                                    this.screens.add(tmpScreen);
                                }
                            }
                        }
                    }
                } else {
                    BT_debugger.showIt(String.valueOf(className) + ":parseJSONData does NOT contain any BT_items?");
                }
            } else {
                BT_debugger.showIt(String.valueOf(className) + ":parseJSONData does NOT contain BT_appConfig?");
            }
        } catch (Exception je) {
            BT_debugger.showIt(String.valueOf(className) + ":parseJSONData JSONObject ERROR: " + je.toString());
        }
        return true;
    }

