    public void updateDeviceConnectionType() {
        String connectionType;
        try {
            Application appDelegate = mspcarshows_appDelegate.getApplication();
            ConnectivityManager mConnectivity = (ConnectivityManager) appDelegate.getSystemService("connectivity");
            NetworkInfo info = mConnectivity.getActiveNetworkInfo();
            if (info == null || !mConnectivity.getBackgroundDataSetting()) {
                connectionType = "NONE";
            } else {
                int netType = info.getType();
                if (netType == 1) {
                    connectionType = "WIFI";
                } else if (netType == 0) {
                    connectionType = "CELL";
                } else {
                    connectionType = "NONE";
                }
            }
            BT_debugger.showIt(String.valueOf(objectName) + ":updateDeviceConnectionType: ConnectionType: " + connectionType);
            this.deviceConnectionType = connectionType;
        } catch (Exception je) {
            BT_debugger.showIt(String.valueOf(objectName) + ":updateDeviceConnectionType ERROR: " + je.toString());
        }
    }

