public class BT_fileManager {
    public static String objectName = "BT_fileManager";

    public static boolean canCacheDocumentType(String theFileName) {
        BT_debugger.showIt(String.valueOf(objectName) + ":canCacheDocument \"" + theFileName + "\"");
        if (theFileName.length() <= 1) {
            return false;
        }
        ArrayList<String> validList = new ArrayList<>();
        validList.add(".htm");
        validList.add(".txt");
        validList.add(".pdf");
        validList.add(".xls");
        validList.add(".ppt");
        validList.add(".doc");
        for (int x = 0; x < validList.size(); x++) {
            if (theFileName.contains(validList.get(x))) {
                return true;
            }
        }
        return false;
    }

    public static boolean doesProjectAssetExist(String assetsDirectory, String fileName) {
        boolean ret = false;
        AssetManager am = mspcarshows_appDelegate.getApplication().getAssets();
        try {
            String[] list = am.list(assetsDirectory);
            if (list != null) {
                int i = 0;
                while (true) {
                    if (i >= list.length) {
                        break;
                    }
                    if (!list[i].equalsIgnoreCase(fileName)) {
                        i++;
                    } else {
                        ret = true;
                        break;
                    }
                }
            }
        } catch (Exception e) {
            BT_debugger.showIt(String.valueOf(objectName) + ":doesProjectAssetExist EXCEPTION " + e.toString());
        }
        if (assetsDirectory.length() > 1) {
            assetsDirectory = String.valueOf(assetsDirectory) + "/";
        }
        if (ret) {
            return true;
        }
        BT_debugger.showIt(String.valueOf(objectName) + ":doesProjectAssetExist: NO assets/" + assetsDirectory + fileName);
        return false;
    }

    public static boolean copyAssetToCache(String assetsDirectory, String fileName) {
        BT_debugger.showIt(String.valueOf(objectName) + ":copyAssetToCache: " + fileName);
        try {
            FileOutputStream outputStream = mspcarshows_appDelegate.getApplication().openFileOutput(fileName, 1);
            InputStream inputStream = mspcarshows_appDelegate.getApplication().getAssets().open(String.valueOf(assetsDirectory) + "/" + fileName);
            byte[] buffer = new byte[8192];
            while (true) {
                int length = inputStream.read(buffer);
                if (length > 0) {
                    outputStream.write(buffer, 0, length);
