    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        this.activityName = "BT_screen_customHTML";
        BT_debugger.showIt(String.valueOf(this.activityName) + ":onCreate");
        LinearLayout baseView = (LinearLayout) findViewById(R.id.baseView);
        BT_viewUtilities.updateBackgroundColorsForScreen(this, this.screenData);
        if (this.backgroundImageWorkerThread == null) {
            this.backgroundImageWorkerThread = new BT_activity_base.BackgroundImageWorkerThread();
            this.backgroundImageWorkerThread.start();
        }
        LinearLayout navBar = BT_viewUtilities.getNavBarForScreen(this, this.screenData);
        if (navBar != null) {
            baseView.addView(navBar);
        }
        LayoutInflater vi = (LayoutInflater) thisActivity.getSystemService("layout_inflater");
        View thisScreensView = vi.inflate(R.layout.screen_customhtml, (ViewGroup) null);
        baseView.addView(thisScreensView);
        this.webView = (WebView) thisScreensView.findViewById(R.id.webView);
        this.webView.setBackgroundColor(0);
        this.webView.setInitialScale(0);
        this.webView.getSettings().setJavaScriptEnabled(true);
        this.webView.getSettings().setSupportZoom(true);
        this.webView.getSettings().setBuiltInZoomControls(true);
        this.webView.getSettings().setPluginsEnabled(true);
        this.webView.setPictureListener(new MyPictureListener());
        this.webView.setWebViewClient(new WebViewClient() { // from class: com.mspcarshows.BT_screen_customHTML.2
            @Override // android.webkit.WebViewClient
            public boolean shouldOverrideUrlLoading(WebView view, String url) {
                BT_screen_customHTML.this.currentURL = url;
                if (BT_act_controller.canLoadDocumentInWebView(url)) {
                    BT_screen_customHTML.this.showProgress(null, null);
                    return false;
                }
                try {
                    Intent i = new Intent("android.intent.action.VIEW", Uri.parse(url));
                    BT_screen_customHTML.this.startActivity(Intent.createChooser(i, BT_screen_customHTML.this.getString(R.string.openWithWhatApp)));
                } catch (Exception e) {
                    BT_debugger.showIt(String.valueOf(BT_screen_customHTML.this.activityName) + ": Error launching native app for url: " + url);
                    BT_screen_customHTML.this.showAlert(BT_screen_customHTML.this.getString(R.string.noNativeAppTitle), BT_screen_customHTML.this.getString(R.string.noNativeAppDescription));
                }
                return true;
            }

            @Override // android.webkit.WebViewClient
            public void onPageFinished(WebView view, String url) {
                BT_screen_customHTML.this.hideProgress();
                BT_debugger.showIt(String.valueOf(BT_screen_customHTML.this.activityName) + ":onPageFinished finished Loading: " + url);
            }

            @Override // android.webkit.WebViewClient
            public void onReceivedError(WebView view, int errorCode, String description, String failingUrl) {
                BT_screen_customHTML.this.hideProgress();
                BT_screen_customHTML.this.showAlert(BT_screen_customHTML.this.getString(R.string.errorTitle), BT_screen_customHTML.this.getString(R.string.errorLoadingScreen));
                String str = ":onReceivedError ERROR loading url: " + failingUrl + " Description: " + description;
                BT_screen_customHTML.this.activityName = str;
                BT_debugger.showIt(str);
            }
        });
        this.dataURL = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "dataURL", "");
        this.localFileName = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "localFileName", "");
        this.forceRefresh = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "forceRefresh", "0");
        this.currentURL = this.dataURL;
        this.originalURL = this.dataURL;
        if (this.localFileName.length() > 1) {
            this.saveAsFileName = this.localFileName;
        } else {
            this.saveAsFileName = String.valueOf(this.screenData.getItemId()) + "_screenData.html";
        }
        if (this.forceRefresh.equalsIgnoreCase("1")) {
            BT_fileManager.deleteFile(this.saveAsFileName);
        }
        this.showBrowserBarBack = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "showBrowserBarBack", "0");
        this.showBrowserBarLaunchInNativeApp = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "showBrowserBarLaunchInNativeApp", "0");
        this.showBrowserBarEmailDocument = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "showBrowserBarEmailDocument", "0");
        this.showBrowserBarRefresh = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "showBrowserBarRefresh", "0");
        String preventUserInteraction = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "preventUserInteraction", "0");
        preventUserInteraction.equalsIgnoreCase("1");
        String hideVerticalScrollBar = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "hideVerticalScrollBar", "0");
        if (hideVerticalScrollBar.equalsIgnoreCase("1")) {
            this.webView.setVerticalScrollBarEnabled(false);
        }
        String hideHorizontalScrollBar = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "hideHorizontalScrollBar", "0");
        if (hideHorizontalScrollBar.equalsIgnoreCase("1")) {
            this.webView.setHorizontalScrollBarEnabled(false);
        }
        String preventAllScrolling = BT_strings.getJsonPropertyValue(this.screenData.getJsonObject(), "preventAllScrolling", "0");
        if (preventAllScrolling.equalsIgnoreCase("1")) {
            this.webView.setVerticalScrollBarEnabled(false);
            this.webView.setHorizontalScrollBarEnabled(false);
        }
        if (this.dataURL.length() > 1) {
            if (BT_fileManager.doesCachedFileExist(this.saveAsFileName) && !this.forceRefresh.equalsIgnoreCase("1")) {
                BT_debugger.showIt(String.valueOf(this.activityName) + ": loading from cache: " + this.saveAsFileName);
                String theData = BT_fileManager.readTextFileFromCache(this.saveAsFileName);
                showProgress(null, null);
                loadDataString(theData);
            } else {
                BT_debugger.showIt(String.valueOf(this.activityName) + ": loading from URL: " + this.dataURL);
                BT_strings.mergeBTVariablesInString(this.dataURL);
                downloadAndSaveFile(this.dataURL, this.saveAsFileName);
            }
        } else if (!BT_fileManager.doesProjectAssetExist("BT_Docs", this.saveAsFileName)) {
            BT_debugger.showIt(String.valueOf(this.activityName) + ": ERROR. HTML file \"" + this.saveAsFileName + "\" does not exist in BT_Docs folder and not URL found? Not loading.");
            showAlert(getString(R.string.errorTitle), getString(R.string.errorLoadingScreen));
        } else {
            BT_debugger.showIt(String.valueOf(this.activityName) + ": loading from BT_Docs: " + this.saveAsFileName);
            showProgress(null, null);
            this.webView.loadUrl("file:///android_asset/BT_Docs/" + this.saveAsFileName);
        }
        this.didCreate = true;
    }

