    public void setMapBoundsToPois(List<GeoPoint> items, double hpadding, double vpadding) {
        BT_debugger.showIt(String.valueOf(this.activityName) + ":showMapPins");
        MapController mapController = this.mapView.getController();
        if (items.size() == 1) {
            mapController.animateTo(items.get(0));
        } else {
            int minLatitude = Integer.MAX_VALUE;
            int maxLatitude = Integer.MIN_VALUE;
            int minLongitude = Integer.MAX_VALUE;
            int maxLongitude = Integer.MIN_VALUE;
            for (GeoPoint item : items) {
                int lat = item.getLatitudeE6();
                int lon = item.getLongitudeE6();
                maxLatitude = Math.max(lat, maxLatitude);
                minLatitude = Math.min(lat, minLatitude);
                maxLongitude = Math.max(lon, maxLongitude);
                minLongitude = Math.min(lon, minLongitude);
            }
            int maxLatitude2 = maxLatitude + ((int) ((maxLatitude - minLatitude) * hpadding));
            int minLatitude2 = minLatitude - ((int) ((maxLatitude2 - minLatitude) * hpadding));
            int maxLongitude2 = maxLongitude + ((int) ((maxLongitude - minLongitude) * vpadding));
            int minLongitude2 = minLongitude - ((int) ((maxLongitude2 - minLongitude) * vpadding));
            mapController.zoomToSpan(Math.abs(maxLatitude2 - minLatitude2), Math.abs(maxLongitude2 - minLongitude2));
            mapController.animateTo(new GeoPoint((maxLatitude2 + minLatitude2) / 2, (maxLongitude2 + minLongitude2) / 2));
        }
        this.mapView.invalidate();
        hideProgress();
    }

