    public void emailDocument() {
        if (mspcarshows_appDelegate.rootApp.getRootDevice().canSendEmail() && BT_fileManager.doesCachedFileExist(this.saveAsFileName)) {
            try {
                BT_fileManager.copyFileFromCacheToSDCard(this.saveAsFileName);
                File file = new File(mspcarshows_appDelegate.getApplication().getExternalCacheDir(), this.saveAsFileName);
                String savedToPath = file.getAbsolutePath();
                if (file.exists()) {
                    String sendFromPath = "file:///sdcard/Android/data/com.mspcarshows/cache/" + this.saveAsFileName;
                    Intent emailIntent = new Intent("android.intent.action.SEND");
                    emailIntent.setType("text/plain");
                    emailIntent.setFlags(268435456);
                    emailIntent.putExtra("android.intent.extra.SUBJECT", getString(R.string.sharingWithYou));
                    emailIntent.putExtra("android.intent.extra.TEXT", "\n\n" + getString(R.string.attachedFile));
                    emailIntent.putExtra("android.intent.extra.STREAM", Uri.parse(sendFromPath));
                    startActivity(emailIntent);
                } else {
                    BT_debugger.showIt(String.valueOf(this.activityName) + ":emailDocument Cannot email document, file does not exist: " + savedToPath);
                }
                return;
            } catch (Exception e) {
                BT_activity_base.showAlertFromClass(getString(R.string.errorTitle), getString(R.string.cannotEmailDocument));
                BT_debugger.showIt(String.valueOf(this.activityName) + ":emailDocument EXCEPTION " + e.toString());
                return;
            }
        }
        BT_activity_base.showAlertFromClass(mspcarshows_appDelegate.getApplication().getString(R.string.errorTitle), getString(R.string.fileNotDownloadedYet));
        BT_debugger.showIt(String.valueOf(this.activityName) + ":emailDocument Cannot email document, cached file does not exist");
    }

    public void openDocInCache(String fileName) {
        BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache: " + fileName);
        if (BT_fileManager.doesCachedFileExist(fileName)) {
            try {
                if (BT_fileManager.doesCachedFileExist(fileName)) {
                    PackageManager pm = getPackageManager();
                    ApplicationInfo appInfo = pm.getApplicationInfo(getPackageName(), 0);
                    File theFile = new File(String.valueOf(appInfo.dataDir) + "/files/" + fileName);
                    Intent intent = new Intent();
                    intent.setAction("android.intent.action.VIEW");
                    Uri uri = Uri.fromFile(theFile);
                    intent.setDataAndType(uri, "application/msword");
                    intent.setFlags(67108864);
                    startActivity(intent);
                } else {
                    BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache: could not copy file to cache");
                }
                return;
            } catch (Exception e) {
                BT_activity_base.showAlertFromClass(getString(R.string.errorTitle), getString(R.string.noNativeAppDescription));
                BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache EXCEPTION " + e.toString());
                return;
            }
        }
        BT_activity_base.showAlertFromClass(getString(R.string.errorTitle), getString(R.string.fileNotDownloadedYet));
        BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache Cannot open document, not in cache yet: " + fileName);
    }

