    public void openDocInCache(String fileName) {
        BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache: " + fileName);
        if (BT_fileManager.doesCachedFileExist(fileName)) {
            try {
                if (BT_fileManager.doesCachedFileExist(fileName)) {
                    PackageManager pm = getPackageManager();
                    ApplicationInfo appInfo = pm.getApplicationInfo(getPackageName(), 0);
                    File theFile = new File(String.valueOf(appInfo.dataDir) + "/files/" + fileName);
                    Intent intent = new Intent();
                    intent.setAction("android.intent.action.VIEW");
                    Uri uri = Uri.fromFile(theFile);
                    intent.setDataAndType(uri, "application/msword");
                    intent.setFlags(67108864);
                    startActivity(intent);
                } else {
                    BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache: could not copy file to cache");
                }
                return;
            } catch (Exception e) {
                BT_activity_base.showAlertFromClass(getString(R.string.errorTitle), getString(R.string.noNativeAppDescription));
                BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache EXCEPTION " + e.toString());
                return;
            }
        }
        BT_activity_base.showAlertFromClass(getString(R.string.errorTitle), getString(R.string.fileNotDownloadedYet));
        BT_debugger.showIt(String.valueOf(this.activityName) + ":openDocInCache Cannot open document, not in cache yet: " + fileName);
    }

