    public static String formatBytes(long bytes, boolean si) {
        BT_debugger.showIt(String.valueOf(objectName) + ":formatBytes Formatting: " + bytes);
        int unit = si ? 1000 : 1024;
        if (bytes < unit) {
            return String.valueOf(bytes) + " B";
        }
        int exp = (int) (Math.log(bytes) / Math.log(unit));
        String pre = String.valueOf((si ? "kMGTPE" : "KMGTPE").charAt(exp - 1)) + (si ? "" : "i");
        return String.format("%.1f %sB", Double.valueOf(bytes / Math.pow(unit, exp)), pre);
    }
