    public static void updateBackgroundColorsForScreen(Activity theActivity, BT_item theScreenData) {
        String backgroundColor;
        BT_debugger.showIt(String.valueOf(objectName) + ":updateBackgroundColorsForScreen with nickname: \"" + theScreenData.getItemNickname() + "\"");
        BT_item theThemeData = mspcarshows_appDelegate.rootApp.getRootTheme();
        RelativeLayout backgroundSolidColorView = (RelativeLayout) theActivity.findViewById(R.id.backgroundSolidColorView);
        if (BT_strings.getJsonPropertyValue(theScreenData.getJsonObject(), "backgroundColor", "").length() > 1) {
            backgroundColor = BT_strings.getJsonPropertyValue(theScreenData.getJsonObject(), "backgroundColor", "");
        } else {
            backgroundColor = BT_strings.getJsonPropertyValue(theThemeData.getJsonObject(), "backgroundColor", "");
        }
        if (backgroundColor.length() > 5) {
            BT_debugger.showIt(String.valueOf(objectName) + ":updateBackgroundColorsForScreen: setting background color to: \"" + backgroundColor + "\"");
            try {
                if (backgroundColor.equalsIgnoreCase("clear")) {
                    backgroundSolidColorView.setBackgroundColor(0);
                    backgroundSolidColorView.setVisibility(0);
                } else {
                    backgroundSolidColorView.setBackgroundColor(BT_color.getColorFromHexString(backgroundColor));
                    backgroundSolidColorView.setVisibility(1);
                }
                backgroundSolidColorView.invalidate();
            } catch (Exception e) {
                BT_debugger.showIt(String.valueOf(objectName) + ":updateBackgroundColorsForScreen: Exception setting background color (\"" + backgroundColor + "\") " + e.toString());
            }
        }
