    public static Bitmap getRoundedImage(Bitmap bitmap, int pixels) {
        Bitmap output = null;
        try {
            output = Bitmap.createBitmap(bitmap.getWidth(), bitmap.getHeight(), Bitmap.Config.ARGB_8888);
            Canvas canvas = new Canvas(output);
            Paint paint = new Paint();
            Rect rect = new Rect(0, 0, bitmap.getWidth(), bitmap.getHeight());
            RectF rectF = new RectF(rect);
            float roundPx = pixels;
            paint.setAntiAlias(true);
            canvas.drawARGB(0, 0, 0, 0);
            paint.setColor(-12434878);
            canvas.drawRoundRect(rectF, roundPx, roundPx, paint);
            paint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.SRC_IN));
            canvas.drawBitmap(bitmap, rect, rect, paint);
            return output;
        } catch (Exception e) {
            BT_debugger.showIt(String.valueOf(objectName) + ":convertToPixels EXCEPTION " + e.toString());
            return output;
        }
    }

    public static Bitmap getScaledBitmap(Bitmap image, int maxHeight, int maxWidth) {
        try {
            int imgWidth = image.getWidth();
            int imgHeight = image.getHeight();
            float scaleFactor = Math.min(maxWidth / imgWidth, maxHeight / imgHeight);
            Matrix scale = new Matrix();
            scale.postScale(scaleFactor, scaleFactor);
            Bitmap scaledImage = Bitmap.createBitmap(image, 0, 0, imgWidth, imgHeight, scale, false);
            return scaledImage;
        } catch (Exception e) {
            BT_debugger.showIt(String.valueOf(objectName) + ":getScaledBitmap EXCEPTION " + e.toString());
            return null;
        }
    }

